<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { cambiarEstadoAgrupadoraConcepto, guardarAgrupadoraConcepto, listarAgrupadorasConceptos } from '../services/agrupadorasConceptos'
import type { AgrupadoraConcepto, AgrupadoraConceptoPayload } from '../interfaces/agrupadorasConceptos.interface'
const rows=ref<AgrupadoraConcepto[]>([]),criterio=ref(''),page=ref(1),lastPage=ref(1),total=ref(0),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),editing=ref<number|null>(null);const form=reactive<AgrupadoraConceptoPayload>({codigo:'',descripcion:''});const message=(v:unknown)=>v instanceof Error?v.message:'No se pudo completar la operación.'
async function load(next=1){loading.value=true;error.value='';try{const r=await listarAgrupadorasConceptos(criterio.value,next);rows.value=r.data;page.value=r.current_page;lastPage.value=r.last_page;total.value=r.total}catch(v){error.value=message(v)}finally{loading.value=false}}
function open(item?:AgrupadoraConcepto){editing.value=item?.id??null;Object.assign(form,item?{codigo:item.codigo,descripcion:item.descripcion}:{codigo:'',descripcion:''});error.value='';modal.value=true}
function validate(){if(form.codigo.trim().length<2||form.codigo.trim().length>20)return 'El código debe tener entre 2 y 20 caracteres.';if(form.descripcion.trim().length<3||form.descripcion.trim().length>150)return 'La descripción debe tener entre 3 y 150 caracteres.';return ''}
async function save(){const issue=validate();if(issue)return void(error.value=issue);saving.value=true;error.value='';try{await guardarAgrupadoraConcepto(editing.value,{codigo:form.codigo.trim().toUpperCase(),descripcion:form.descripcion.trim().toUpperCase()});modal.value=false;success.value=`Agrupadora ${editing.value?'actualizada':'registrada'} correctamente.`;await load(editing.value?page.value:1)}catch(v){error.value=message(v)}finally{saving.value=false}}
async function toggle(item:AgrupadoraConcepto){const action=item.estado?'desactivar':'activar';if(!confirm(`¿Desea ${action} la agrupadora ${item.descripcion}?`))return;try{const r=await cambiarEstadoAgrupadoraConcepto(item.id);item.estado=r.estado;success.value=r.message??`Agrupadora ${item.estado?'activada':'desactivada'} correctamente.`}catch(v){error.value=message(v)}}
function clear(){criterio.value='';load(1)};onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Recursos Humanos / Agrupadoras de conceptos</nav><header class="hero"><div class="mark">AC</div><div><small>MIA · RECURSOS HUMANOS · MAESTROS</small><h1>Agrupadoras de conceptos</h1><p>Grupos funcionales para organizar conceptos dentro del cálculo de planillas.</p></div><strong>{{total}} registros</strong><button @click="open()">+ Nueva agrupadora</button></header><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash">{{error}}</p><form class="filters" @submit.prevent="load(1)"><label>Buscar por código o descripción<input v-model.trim="criterio" placeholder="Ej. INGRESOS FIJOS"></label><button>Buscar</button><button type="button" class="soft" @click="clear">Limpiar</button></form><section class="table-card"><header><small>ORGANIZACIÓN DE CONCEPTOS</small><h2>Agrupadoras registradas</h2></header><div v-if="loading" class="empty">Consultando agrupadoras…</div><div v-else-if="!rows.length" class="empty">No se encontraron agrupadoras.</div><div v-else class="scroll"><table><thead><tr><th>ID</th><th>Código</th><th>Descripción</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="x in rows" :key="x.id"><td>{{x.id}}</td><td><b>{{x.codigo}}</b></td><td>{{x.descripcion}}</td><td><span :class="x.estado?'active':'inactive'">{{x.estado?'Activo':'Inactivo'}}</span></td><td class="actions"><button class="edit" @click="open(x)">Editar</button><button :class="x.estado?'disable':'enable'" @click="toggle(x)">{{x.estado?'Desactivar':'Activar'}}</button></td></tr></tbody></table></div><footer v-if="lastPage>1"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>Página {{page}} de {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer></section><div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="dialog" @submit.prevent="save"><header><div class="mark">AC</div><div><small>ORGANIZACIÓN DE CONCEPTOS</small><h2>{{editing?'Editar':'Registrar'}} agrupadora</h2></div><button type="button" @click="modal=false">×</button></header><div class="grid"><label>Código *<input v-model="form.codigo" maxlength="20" @input="form.codigo=form.codigo.toUpperCase()"></label><label>Descripción *<input v-model="form.descripcion" maxlength="150" @input="form.descripcion=form.descripcion.toUpperCase()"></label></div><aside v-if="form.codigo||form.descripcion"><small>VISTA PREVIA</small><p><b>{{form.codigo||'[CÓDIGO]'}}</b><span>{{form.descripcion||'[DESCRIPCIÓN]'}}</span></p></aside><footer><button type="button" class="soft" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':editing?'Actualizar':'Registrar'}}</button></footer></form></div></div></template>
<style scoped>
.page{--accent:#8b5a9c;color:#35464e}nav{margin-bottom:16px;color:#929fa5;font-size:.68rem}nav a{color:var(--accent);text-decoration:none}.hero{padding:20px 23px;display:flex;align-items:center;gap:14px;border-left:5px solid var(--accent);border-radius:12px;background:#fff}.mark{width:48px;height:48px;display:grid;place-items:center;border-radius:10px;color:#fff;background:var(--accent);font-size:.62rem;font-weight:800}.hero small,.table-card small,.dialog small{color:var(--accent);font-size:.48rem;font-weight:800}.hero h1{margin:2px 0;font-size:1.3rem}.hero p{margin:0;color:#7e8a90;font-size:.67rem}.hero strong{margin-left:auto;padding:6px 9px;border-radius:12px;color:var(--accent);background:#f6edf8;font-size:.52rem}.hero button,.filters button,.table-card footer button,.dialog button{padding:9px 12px;border:0;border-radius:6px;color:#fff;background:var(--accent);font-size:.52rem}.flash{padding:9px;border-radius:7px;color:#a64046;background:#fff0f0;font-size:.6rem}.flash.success{color:#287052;background:#edf9f3}.filters{margin-top:10px;padding:13px;display:flex;align-items:end;gap:6px;border-radius:9px;background:#fff}.filters label{margin-right:auto;width:min(500px,100%);font-size:.52rem}.filters input,.dialog input{width:100%;box-sizing:border-box;margin-top:4px;padding:8px;border:1px solid #d7dfe2;border-radius:6px;background:#fff;font:inherit;font-size:.54rem}.soft{color:#64727a!important;background:#edf1f3!important}.table-card{margin-top:10px;border-radius:10px;background:#fff;overflow:hidden}.table-card>header{padding:13px 15px;border-bottom:1px solid #e7ebed}.table-card h2{margin:2px 0;font-size:.78rem}.scroll{overflow:auto}table{width:100%;min-width:700px;border-collapse:collapse;font-size:.52rem}th,td{padding:9px;border-bottom:1px solid #e8ecee;text-align:left}th{color:#fff;background:#5b6e8e}.active,.inactive{display:inline-block;padding:4px 7px;border-radius:10px;font-size:.42rem}.active{color:#287154;background:#e6f7ee}.inactive{color:#9d4046;background:#fdebed}.actions{display:flex;gap:5px}.actions button{padding:6px 8px;border:0;border-radius:5px;font-size:.46rem}.edit{color:#79500b;background:#ffe7bd}.disable{color:#9d4046;background:#fdebed}.enable{color:#287154;background:#e6f7ee}.empty{padding:45px;text-align:center;font-size:.6rem}.table-card>footer{padding:10px;display:flex;justify-content:center;align-items:center;gap:9px;font-size:.52rem}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#172b3d88}.dialog{width:min(680px,100%);padding:20px;box-sizing:border-box;border-radius:12px;background:#fff}.dialog>header{display:flex;align-items:center;gap:9px}.dialog h2{margin:2px 0 12px;font-size:.9rem}.dialog>header>button{margin-left:auto;color:#59666c;background:none;font-size:1.2rem}.dialog label{display:grid;margin-top:8px;font-size:.5rem}.grid{display:grid;grid-template-columns:1fr 2fr;gap:9px}.dialog aside{margin-top:14px;padding:12px;border-radius:7px;background:#f7f8f9}.dialog aside p{margin:6px 0 0;display:flex;gap:10px;font-size:.52rem}.dialog aside span{flex:1}.dialog>footer{margin-top:16px;display:flex;justify-content:flex-end;gap:6px}@media(max-width:760px){.hero,.filters{flex-wrap:wrap}.hero strong{margin-left:0}.filters label{width:100%}.grid{grid-template-columns:1fr}.actions{min-width:140px}}
</style>
